// Generated by Suite Builder from a crawl of the site. Page timings in every run: target/timings/timings.csv, the slowest listed at the end.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Fail a run on a slow page with -DloadBudget (seconds).
package com.playwrightplayground.tests.core;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Page timings, in every run: each time a page's checks pass (LoadablePage.get()), a row in
 * target/timings/timings.csv: the test, the page, its path and, in milliseconds from the start of
 * its navigation, when it was ready (its checks passed), its first byte, DOM loaded and load event;
 * then how long it went on working after its load event, and what the crawl timed of that for its
 * type. At the end of the run the slowest pages are listed, and any page flagged slow: much longer
 * after its load event than the crawl saw (3 times, and 1000 ms more), or
 * ready much later than in the previous run (target/timings-previous/), or ready past
 * 50% of its time limit (-DpageLoadTimeout): it passed, and a slower day fails it. Report-only:
 * -DloadBudget=2.5 (seconds) fails a test whose page takes longer than that to be ready. Not load
 * testing: one visitor, as the tests go.
 */
public final class Timings {
    public static final String COLUMNS = "test,page,path,ready_ms,first_byte_ms,dom_loaded_ms,load_ms,after_load_ms,crawl_after_load_ms,slow";
    private static final Path FILE = Path.of("target", "timings", "timings.csv");
    private static final Path PREVIOUS = Path.of("target", "timings-previous", "timings.csv");
    private static final double FACTOR = 3;
    private static final long MARGIN_MS = 1000;
    private static final double NEAR_LIMIT = 0.5;
    private static final String BUDGET = SiteConfig.value("loadBudget", "");
    /** The last run's ready time per test and path, read as this run's first row is written. */
    private static Map<String, Long> before;
    private static final List<String[]> ROWS = new ArrayList<>();
    /** The test each thread is running (test classes may run at once: -Dthreads). */
    private static final ThreadLocal<String> TEST = ThreadLocal.withInitial(() -> "");
    /** The navigation and page each thread last recorded: a page checked twice (open(), then verify().isLoaded()) is one row. */
    private static final ThreadLocal<String> LAST = new ThreadLocal<>();

    private Timings() {}

    /** BaseTest, before each test: the name its rows carry. */
    public static synchronized void startTest(String name) {
        TEST.set(name);
    }

    /**
     * A page's checks have passed: its row. `times` is the browser's "ready,firstByte,domLoaded,load,start"
     * (empty where it records none; start, the navigation's, tells one navigation checked twice from two);
     * `crawlSettledMs` what the crawl saw after the load event, or -1.
     */
    public static synchronized void record(String page, String path, String times, long crawlSettledMs) {
        String[] t = times == null ? new String[0] : times.split(",");
        if (t.length < 4) return;
        // The same navigation and page again (a single-page app's next page shares its navigation, not its path).
        String seen = t.length > 4 ? t[4] + " " + path : null;
        if (seen != null && seen.equals(LAST.get())) return;
        // A single-page app's route change (the same navigation, another path): its times count from the
        // page it was reached from, clicks included, so it is never judged against a load event (Site G's run).
        boolean routed = seen != null && LAST.get() != null && LAST.get().startsWith(t[4] + " ");
        LAST.set(seen);
        long ready = Long.parseLong(t[0]);
        long load = Long.parseLong(t[3]);
        long afterLoad = load > 0 ? Math.max(0, ready - load) : 0;
        List<String> slow = new ArrayList<>();
        if (!routed && crawlSettledMs >= 0 && afterLoad > crawlSettledMs * FACTOR && afterLoad - crawlSettledMs > MARGIN_MS) {
            slow.add(afterLoad + " ms after its load event, where the crawl saw " + crawlSettledMs + " ms for its type");
        }
        String test = TEST.get();
        Long earlier = previous().get(test + "\n" + path);
        if (earlier != null && ready > earlier * FACTOR && ready - earlier > MARGIN_MS) {
            slow.add("ready in " + ready + " ms, where the previous run took " + earlier + " ms");
        }
        if (!routed && ready > WaitActions.PAGE_LOAD_TIMEOUT * NEAR_LIMIT) {
            slow.add("ready in " + ready + " ms, " + Math.round(ready * 100.0 / WaitActions.PAGE_LOAD_TIMEOUT) + "% of its time limit ("
                    + WaitActions.PAGE_LOAD_TIMEOUT + " ms, -DpageLoadTimeout): it passed, and a slower day fails it");
        }
        String[] row = {test, page, path, t[0], t[1], t[2], t[3], String.valueOf(afterLoad), crawlSettledMs < 0 ? "" : String.valueOf(crawlSettledMs), String.join("; ", slow)};
        ROWS.add(row);
        write(row);
        if (!BUDGET.isBlank() && ready > Double.parseDouble(BUDGET) * 1000) {
            throw new AssertionError(page + " took " + ready + " ms to be ready at " + path + ", over the budget of " + BUDGET + " s (-DloadBudget)");
        }
    }

    /** At the end of the run (RunReport): the slowest pages, and those flagged slow. */
    public static synchronized String report() {
        if (ROWS.isEmpty()) return "";
        List<String[]> rows = new ArrayList<>(ROWS);
        rows.sort(Comparator.comparingLong((String[] r) -> Long.parseLong(r[3])).reversed());
        StringBuilder out = new StringBuilder("\nPage timings (" + FILE + ", " + rows.size() + " pages reached). The slowest:\n");
        for (String[] r : rows.subList(0, Math.min(5, rows.size()))) out.append("   ").append(r[3]).append(" ms  ").append(r[1]).append(' ').append(r[2]).append('\n');
        for (String[] r : rows) if (!r[9].isEmpty()) out.append("   SLOW: ").append(r[1]).append(' ').append(r[2]).append(" (").append(r[0]).append("): ").append(r[9]).append('\n');
        return out.toString();
    }

    private static Map<String, Long> previous() {
        if (before != null) return before;
        before = new HashMap<>();
        try {
            if (Files.exists(FILE)) {
                Files.createDirectories(PREVIOUS.getParent());
                Files.move(FILE, PREVIOUS, StandardCopyOption.REPLACE_EXISTING);
            }
            if (Files.exists(PREVIOUS)) {
                List<String> lines = Files.readAllLines(PREVIOUS, StandardCharsets.UTF_8);
                for (String line : lines.subList(Math.min(1, lines.size()), lines.size())) {
                    List<String> cells = cells(line);
                    if (cells.size() > 3 && !cells.get(3).isEmpty()) before.put(cells.get(0) + "\n" + cells.get(2), Long.parseLong(cells.get(3)));
                }
            }
            Files.createDirectories(FILE.getParent());
            Files.writeString(FILE, COLUMNS + System.lineSeparator(), StandardCharsets.UTF_8);
        } catch (IOException | RuntimeException e) {
            System.out.println("   note: page timings not kept (" + e.getMessage() + ")");
        }
        return before;
    }

    private static void write(String[] row) {
        StringBuilder line = new StringBuilder();
        for (String cell : row) line.append(line.length() > 0 ? "," : "").append('"').append(cell.replace("\"", "\"\"")).append('"');
        try {
            Files.writeString(FILE, line + System.lineSeparator(), StandardCharsets.UTF_8, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.out.println("   note: page timing not written (" + e.getMessage() + ")");
        }
    }

    /** A CSV line's cells, each quoted as write() quotes them. */
    private static List<String> cells(String line) {
        List<String> out = new ArrayList<>();
        StringBuilder cell = new StringBuilder();
        boolean quoted = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (quoted && c == '"' && i + 1 < line.length() && line.charAt(i + 1) == '"') {
                cell.append('"');
                i++;
            } else if (c == '"') {
                quoted = !quoted;
            } else if (c == ',' && !quoted) {
                out.add(cell.toString());
                cell.setLength(0);
            } else {
                cell.append(c);
            }
        }
        out.add(cell.toString());
        return out;
    }
}
